const M={session:'VariableID:18:4753',read:'VariableID:18:4754',readOpen:'VariableID:18:4755',closed:'VariableID:18:4756',theme:'VariableID:18:4757',snapshot:'VariableID:18:4758',focus:'VariableID:18:4759',wallet:'VariableID:18:4760',available:'VariableID:18:4761',selected:'VariableID:9:6182',context:'VariableID:9:6183',order:'VariableID:79:5104',unknown:'VariableID:105:5610',failed:'VariableID:105:5609',chapter:'VariableID:124:5777',created:'VariableID:124:5773',moved:'VariableID:130:6958',onSunday:'VariableID:130:6959',themeOpen:'VariableID:124:5779',chapterOpen:'VariableID:124:5778',themeAtClosure:'VariableID:124:5775',chapterAtClosure:'VariableID:124:5780',createdAtClosure:'VariableID:124:5774',applied:'VariableID:91:5604',carry:'VariableID:23:4741',about:'VariableID:84:5202'};
const cache=new Map(),nodeCache=new Map();async function node(id){if(!nodeCache.has(id))nodeCache.set(id,await figma.getNodeByIdAsync(id));return nodeCache.get(id)}function rx(n){if(!cache.has(n.id))cache.set(n.id,n.reactions||[]);return cache.get(n.id)}
function env(o={}){const e=new Map();const base={session:'idle',read:false,readOpen:true,closed:false,theme:true,snapshot:false,focus:'45 / 60 min saved today',wallet:'Coins · 33',available:'33 coins available',selected:'Read the primary source',context:'History seminar / Prepare seminar discussion',order:false,unknown:false,failed:false,chapter:true,created:false,moved:false,onSunday:true,themeOpen:false,chapterOpen:false,themeAtClosure:true,chapterAtClosure:true,createdAtClosure:false,applied:'0',carry:'none',about:false};for(const[k,v]of Object.entries({...base,...o}))e.set(M[k]||k,v);return e}
function ev(x,e){if(x==null)return true;if(x.type==='VARIABLE_ALIAS')return e.get(x.value.id);if(x.type!=='EXPRESSION')return x.value;const a=x.value.expressionArguments.map(z=>ev(z,e));switch(x.value.expressionFunction){case'EQUALS':return a[0]===a[1];case'NOT_EQUAL':return a[0]!==a[1];case'AND':return a.every(Boolean);case'OR':return a.some(Boolean);case'NOT':return !a[0];case'ADDITION':return a[0]+a[1];case'SUBTRACTION':return a[0]-a[1];case'MULTIPLICATION':return a[0]*a[1];case'DIVISION':return a[0]/a[1];default:throw Error('Unsupported '+x.value.expressionFunction)}}
function run(actions,e,to=[]){for(const a of actions||[]){if(a.type==='SET_VARIABLE')e.set(a.variableId,ev(a.variableValue,e));else if(a.type==='NODE')to.push(a.destinationId);else if(a.type==='CONDITIONAL'){for(const b of a.conditionalBlocks)if(ev(b.condition,e)){run(b.actions,e,to);break}}else if(a.type!=='SET_VARIABLE_MODE')throw Error('Unsupported action '+a.type)}return to}
async function click(id,e){const n=await node(id),r=rx(n).find(r=>r.trigger?.type==='ON_CLICK');if(!r)throw Error('Missing click '+id);const to=run(r.actions,e);if(to.length>1)throw Error('Multiple destinations '+id+' '+to);let at=to[0]||null;for(let i=0;i<8&&at;i++){const n=await node(at);if(!n)throw Error('Missing destination '+at);const next=[];for(const r of rx(n).filter(r=>r.trigger?.type==='AFTER_TIMEOUT'))run(r.actions,e,next);if(next.length>1)throw Error('Multiple entry destinations '+next);if(!next.length)return at;if(next[0]===at)throw Error('Self-entry '+at);at=next[0]}return at}
const results=[],counts={},failures=[];async function test(group,name,fn){counts[group]=(counts[group]||0)+1;try{await fn();results.push({group,name,status:'Pass'})}catch(err){const x={group,name,status:'Fail',detail:String(err.message||err)};results.push(x);failures.push(x)}}
function assert(ok,msg){if(!ok)throw Error(msg)}
const daily=['5:4391','5:4893','5:4997','5:5100','5:5212','5:5275','5:5367','5:5428','5:5489','7:2865','9:6144'];
const dailyStates={running:['5:4551','14:3247'],paused:['14:3112','14:3293'],review:['14:3157','14:3339'],sleep:['14:3202','14:3385'],finished:['14:3431','14:3471']};
for(const id of daily)for(const session of['idle','running','paused','review','sleep','finished'])for(const read of[false,true])for(const order of[false,true])await test('daily-return',id+' '+session+' read'+read+' order'+order,async()=>{const e=env({session,read,readOpen:!read,order});const to=await click(id,e),expected=session==='idle'?(read?'5:4109':order?'79:5105':'5:3972'):dailyStates[session][+read];assert(to===expected,'Expected '+expected+' got '+to);assert(e.get(M.session)===session,'Session changed '+session+' to '+e.get(M.session));assert(e.get(M.wallet)==='Coins · 33'&&e.get(M.focus)==='45 / 60 min saved today','Return awarded credit');});
for(const id of daily)for(const error of['failed','unknown'])for(const read of[false,true])await test('daily-error-return',id+' '+error+' read'+read,async()=>{const e=env({session:'paused',read,readOpen:!read,[error]:true});const to=await click(id,e);assert(to===(read?'14:3293':'14:3112'),'Wrong error daily destination '+to);assert(e.get(M.session)==='paused'&&e.get(M[error])===true,'Return erased pending/error session');});
