for(const id of['7:2898','7:2978','7:3034'])for(const session of['idle','running','paused','review','sleep','finished'])for(const read of[false,true])await test('track-return',id+' '+session+' read'+read,async()=>{const e=env({session,read,readOpen:!read});const to=await click(id,e),expected=['idle','finished'].includes(session)?(read?'17:4429':'7:2586'):({running:'7:2639',paused:'7:2686',review:'7:2733',sleep:'7:2780'})[session];assert(to===expected,'Expected '+expected+' got '+to);assert(!['running','paused','review','sleep'].includes(session)||e.get(M.session)===session,'Changed active lifecycle');assert(e.get(M.wallet)==='Coins · 33'&&e.get(M.focus)==='45 / 60 min saved today','Return awarded time');});
for(const id of['7:2898','7:2978','7:3034'])for(const error of['failed','unknown'])await test('track-error-return',id+' '+error,async()=>{const e=env({session:'paused',[error]:true});const to=await click(id,e);assert(to===(error==='failed'?'105:5656':'105:5693'),'Wrong recovery '+to);assert(e.get(M.session)==='paused'&&e.get(M[error])===true,'Erased failure/outcome state');});
